package Revision;

public class Operators {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=10;
		int y=a++;
		System.out.println(a);
		System.out.println(y);
		
		if(a>12 && a >10 )
			System.out.println(true);
		System.out.println(false);
		
		if(a>10 & a<50)
			System.out.println(true);

		System.out.println(false);
	}

}
